 if(existing.some(p=>String(p.sku||"").startsWith("DEMO-")))throw Error("داده‌های آزمایشی قبلاً بارگذاری شده‌اند؛ دوباره اضافه نشدند");
 if(existing.length||partiesNow.length||vouchersNow.length||ledgerNow.length||treasuryNow.length||invoicesNow.length||checksNow.length||importsNow.length||shipmentsNow.length||adjustmentsNow.length||accountsNow.some(a=>Number(a.openingDebitRial||0)!==0||Number(a.openingCreditRial||0)!==0))throw Error("برای جلوگیری از تغییر مانده‌ها و اطلاعات واقعی، داده آزمایشی فقط در دفتر کاملاً خالی قابل بارگذاری است");
 const now=Date.now();
 const products=[
  {sku:"DEMO-FDY-75-W",name:"نخ FDY سفید 75D",group:"پلی‌استر",yarn:"FDY",color:"سفید",denier:75,twisted:false,stock:500,value:600000000,avg:1200000,notes:"کالای آزمایشی"},
  {sku:"DEMO-FDY-75-B",name:"نخ FDY مشکی 75D",group:"پلی‌استر",yarn:"FDY",color:"مشکی",denier:75,twisted:false,stock:300,value:390000000,avg:1300000,notes:"کالای آزمایشی"},
  {sku:"DEMO-DTY-150-W",name:"نخ DTY سفید 150D",group:"پلی‌استر",yarn:"DTY",color:"سفید",denier:150,twisted:true,stock:200,value:300000000,avg:1500000,notes:"کالای آزمایشی"}
 ];
 const parties=[
  {name:"شرکت نساجی نمونه آریا",kind:"CUSTOMER",phone:"021-55501010",address:"تهران - نمونه",balance:85000000},
  {name:"بازرگانی نخ شرق",kind:"SUPPLIER",phone:"021-55502020",address:"تهران - نمونه",balance:-45000000},
  {name:"واسطه نمونه پارس",kind:"BOTH",phone:"09120000000",address:"اصفهان - نمونه",balance:0}
 ];
 const accounts=await all("accounts");const old=new Map(accounts.map(a=>[String(a.id),a]));
 const opening=[["1101",250000000,0],["1102",350000000,0],["1103",85000000,0],["1301",1290000000,0],["2101",0,45000000],["2102",0,0],["2103",0,0],["3101",0,1930000000],["4101",0,0],["5101",0,0]];
 const accountRows=opening.map(([code,debit,credit])=>({...old.get(code),id:code,openingDebitRial:debit,openingCreditRial:credit}));
 if(accountRows.reduce((n,a)=>n+a.openingDebitRial,0)!==accountRows.reduce((n,a)=>n+a.openingCreditRial,0))throw Error("مانده افتتاحیه داده نمونه تراز نیست");
 const journal=[{accountCode:"1101",debitRial:250000000,creditRial:0},{accountCode:"1102",debitRial:350000000,creditRial:0},{accountCode:"1103",debitRial:85000000,creditRial:0},{accountCode:"1301",debitRial:1290000000,creditRial:0},{accountCode:"2101",debitRial:0,creditRial:45000000},{accountCode:"3101",debitRial:0,creditRial:1930000000}];
 const entries=[...products.map(p=>["products",{...p,date:now}]),...parties.map(p=>["parties",{...p,date:now}]),...accountRows.map(a=>["accounts",a])];
  const emptyStores=["products","parties","vouchers","partyLedger","treasury","invoices","checks","imports","importShipments","stockAdjustments"];
  const guards=[...emptyStores.map(store=>({store,match:{},expected:null})),...accounts.map(account=>({store:"accounts",key:account.id,expected:{openingDebitRial:account.openingDebitRial,openingCreditRial:account.openingCreditRial}}))];
  await putManyGuarded(entries,guards);
