function partyStatementRows(party,ledger){
 const rows=ledger.filter(r=>Number(r.partyId)===Number(party.id)).sort((a,b)=>Number(a.date||0)-Number(b.date||0));
 const movement=rows.reduce((n,r)=>n+Number(r.debitRial||0)-Number(r.creditRial||0),0);
 const opening=Number(party.balance||0)-movement;let balance=opening;
 const openingRow='<tr><td>—</td><td>مانده افتتاحیه</td><td>'+money(Math.max(0,opening))+'</td><td>'+money(Math.max(0,-opening))+'</td><td>'+money(Math.abs(opening))+' '+(opening>=0?"بدهکار":"بستانکار")+'</td></tr>';
 return openingRow+rows.map(r=>{balance+=Number(r.debitRial||0)-Number(r.creditRial||0);return '<tr><td>'+date(r.date)+'</td><td>'+h(r.description)+'</td><td>'+money(r.debitRial||0)+'</td><td>'+money(r.creditRial||0)+'</td><td>'+money(Math.abs(balance))+' '+(balance>=0?"بدهکار":"بستانکار")+'</td></tr>'}).join('');
}
